#include "DropActor.h"
#include "Components/StaticMeshComponent.h"

ADropActor::ADropActor()
{
	PrimaryActorTick.bCanEverTick = true;

	// RootScene/PickupMesh/CollisionComponent are constructed by the
	// APickupActor base constructor (same default SM_Weapon visual + box
	// collision a fresh pickup gets), so a dropped item is recognized by
	// PickupInteractionComponent's existing APickupActor-based queries with
	// no changes there.
	DropState = EDropActorState::Dropped;

	DropVelocity = FVector(0.0f, 0.0f, -500.0f);
	Bounciness = 0.3f;
	Friction = 0.5f;
}

void ADropActor::BeginPlay()
{
	Super::BeginPlay();

	// Enable physics simulation on the drop mesh
	if (PickupMesh)
	{
		PickupMesh->SetSimulatePhysics(true);
		DropState = EDropActorState::PhysicsSimulating;

		// Apply initial drop velocity
		PickupMesh->AddImpulse(DropVelocity, NAME_None, true);
	}
}

void ADropActor::Tick(float DeltaTime)
{
	Super::Tick(DeltaTime);

	if (DropState == EDropActorState::PhysicsSimulating)
	{
		// Check if physics has stabilized (velocity below threshold)
		if (PickupMesh && PickupMesh->IsSimulatingPhysics())
		{
			float Speed = PickupMesh->GetPhysicsLinearVelocity().Size();

			if (Speed < 10.0f)
			{
				// Item has stabilized, transition to Stabilized state
				Stabilize();
			}
		}
	}
}

void ADropActor::GetLifetimeReplicatedProps(TArray<FLifetimeProperty>& OutLifetimeProps) const
{
	Super::GetLifetimeReplicatedProps(OutLifetimeProps);
}

EDropActorState ADropActor::GetDropState() const
{
	return DropState;
}

void ADropActor::EnablePhysicsSimulation()
{
	if (PickupMesh && !PickupMesh->IsSimulatingPhysics())
	{
		PickupMesh->SetSimulatePhysics(true);

		DropState = EDropActorState::PhysicsSimulating;

		// Apply initial drop velocity if provided
		if (DropVelocity.SizeSquared() > 0.0f)
		{
			PickupMesh->AddImpulse(DropVelocity, NAME_None, true);
		}
	}
}

void ADropActor::Stabilize()
{
	if (PickupMesh && PickupMesh->IsSimulatingPhysics())
	{
		PickupMesh->SetSimulatePhysics(false);
		PickupMesh->SetEnableGravity(true);

		// Lock all transforms to prevent further movement
		PickupMesh->SetWorldLocationAndRotation(PickupMesh->GetComponentLocation(), PickupMesh->GetComponentRotation(), false, nullptr, ETeleportType::None);

		DropState = EDropActorState::Stabilized;
	}
}
